# 📜 Storybook chapter 3 per level (R20 Storybook wave 2, 2026-11-03): each realm's tale carries on after chapter 2.
# Same shape as tools/c_stories2.py, plus hand-written "why not" notes: N = the three wrong options' notes, in order.
# The FIRST option is always correct (shuffled at runtime). {hero} and {pet} are filled in at runtime.
def P(text, q, opts, explain, notes, kind):
    return {"text": text, "q": Q(q, opts, explain, notes, kind)}
def Q(q, opts, explain, notes, kind="vocab"):
    assert len(notes) == 3, q
    return {"q": q, "options": opts, "answer": 0, "explain": explain, "kind": kind, "notes": dict(zip(opts[1:], notes))}
